29|uint32_t FUZZ_dataProducer_uint32Range(FUZZ_dataProducer_t *producer, uint32_t min,
30|                                  uint32_t max) {
31|    FUZZ_ASSERT(min <= max);
32|
33|    uint32_t range = max - min;
34|    uint32_t rolling = range;
35|    uint32_t result = 0;
36|
37|    while (rolling > 0 && producer->size > 0) {
38|      uint8_t next = *(producer->data + producer->size - 1);
39|      producer->size -= 1;
40|      result = (result << 8) | next;
41|      rolling >>= 8;
42|    }
43|
44|    if (range == 0xffffffff) {
45|      return result;
46|    }
47|
48|    return min + result % (range + 1);
49|}

1426|static U32 ZSTD_dictAndWindowLog(U32 windowLog, U64 srcSize, U64 dictSize)
1427|{
1428|    const U64 maxWindowSize = 1ULL << ZSTD_WINDOWLOG_MAX;
1429|    /* No dictionary ==> No change */
1430|    if (dictSize == 0) {
1431|        return windowLog;
1432|    }
1433|    assert(windowLog <= ZSTD_WINDOWLOG_MAX);
1434|    assert(srcSize != ZSTD_CONTENTSIZE_UNKNOWN); /* Handled in ZSTD_adjustCParams_internal() */
1435|    {
1436|        U64 const windowSize = 1ULL << windowLog;
1437|        U64 const dictAndWindowSize = dictSize + windowSize;
1438|        /* If the window size is already large enough to fit both the source and the dictionary
1439|         * then just use the window size. Otherwise adjust so that it fits the dictionary and
1440|         * the window.
1441|         */
1442|        if (windowSize >= dictSize + srcSize) {
1443|            return windowLog; /* Window size large enough already */
1444|        } else if (dictAndWindowSize >= maxWindowSize) {
1445|            return ZSTD_WINDOWLOG_MAX; /* Larger than max window log */
1446|        } else  {
1447|            return ZSTD_highbit32((U32)dictAndWindowSize - 1) + 1;
1448|        }
1449|    }
1450|}

1459|static ZSTD_compressionParameters
1460|ZSTD_adjustCParams_internal(ZSTD_compressionParameters cPar,
1461|                            unsigned long long srcSize,
1462|                            size_t dictSize,
1463|                            ZSTD_cParamMode_e mode,
1464|                            ZSTD_paramSwitch_e useRowMatchFinder)
1465|{
1466|    const U64 minSrcSize = 513; /* (1<<9) + 1 */
1467|    const U64 maxWindowResize = 1ULL << (ZSTD_WINDOWLOG_MAX-1);
1468|    assert(ZSTD_checkCParams(cPar)==0);
1469|
1470|    /* Cascade the selected strategy down to the next-highest one built into
1471|     * this binary. */
1472|#ifdef ZSTD_EXCLUDE_BTULTRA_BLOCK_COMPRESSOR
1473|    if (cPar.strategy == ZSTD_btultra2) {
1474|        cPar.strategy = ZSTD_btultra;
1475|    }
1476|    if (cPar.strategy == ZSTD_btultra) {
1477|        cPar.strategy = ZSTD_btopt;
1478|    }
1479|#endif
1480|#ifdef ZSTD_EXCLUDE_BTOPT_BLOCK_COMPRESSOR
1481|    if (cPar.strategy == ZSTD_btopt) {
1482|        cPar.strategy = ZSTD_btlazy2;
1483|    }
1484|#endif
1485|#ifdef ZSTD_EXCLUDE_BTLAZY2_BLOCK_COMPRESSOR
1486|    if (cPar.strategy == ZSTD_btlazy2) {
1487|        cPar.strategy = ZSTD_lazy2;
1488|    }
1489|#endif
1490|#ifdef ZSTD_EXCLUDE_LAZY2_BLOCK_COMPRESSOR
1491|    if (cPar.strategy == ZSTD_lazy2) {
1492|        cPar.strategy = ZSTD_lazy;
1493|    }
1494|#endif
1495|#ifdef ZSTD_EXCLUDE_LAZY_BLOCK_COMPRESSOR
1496|    if (cPar.strategy == ZSTD_lazy) {
1497|        cPar.strategy = ZSTD_greedy;
1498|    }
1499|#endif
1500|#ifdef ZSTD_EXCLUDE_GREEDY_BLOCK_COMPRESSOR
1501|    if (cPar.strategy == ZSTD_greedy) {
1502|        cPar.strategy = ZSTD_dfast;
1503|    }
1504|#endif
1505|#ifdef ZSTD_EXCLUDE_DFAST_BLOCK_COMPRESSOR
1506|    if (cPar.strategy == ZSTD_dfast) {
1507|        cPar.strategy = ZSTD_fast;
1508|        cPar.targetLength = 0;
1509|    }
1510|#endif
1511|
1512|    switch (mode) {
1513|    case ZSTD_cpm_unknown:
1514|    case ZSTD_cpm_noAttachDict:
1515|        /* If we don't know the source size, don't make any
1516|         * assumptions about it. We will already have selected
1517|         * smaller parameters if a dictionary is in use.
1518|         */
1519|        break;
1520|    case ZSTD_cpm_createCDict:
1521|        /* Assume a small source size when creating a dictionary
1522|         * with an unknown source size.
1523|         */
1524|        if (dictSize && srcSize == ZSTD_CONTENTSIZE_UNKNOWN)
1525|            srcSize = minSrcSize;
1526|        break;
1527|    case ZSTD_cpm_attachDict:
1528|        /* Dictionary has its own dedicated parameters which have
1529|         * already been selected. We are selecting parameters
1530|         * for only the source.
1531|         */
1532|        dictSize = 0;
1533|        break;
1534|    default:
1535|        assert(0);
1536|        break;
1537|    }
1538|
1539|    /* resize windowLog if input is small enough, to use less memory */
1540|    if ( (srcSize <= maxWindowResize)
1541|      && (dictSize <= maxWindowResize) )  {
1542|        U32 const tSize = (U32)(srcSize + dictSize);
1543|        static U32 const hashSizeMin = 1 << ZSTD_HASHLOG_MIN;
1544|        U32 const srcLog = (tSize < hashSizeMin) ? ZSTD_HASHLOG_MIN :
1545|                            ZSTD_highbit32(tSize-1) + 1;
1546|        if (cPar.windowLog > srcLog) cPar.windowLog = srcLog;
1547|    }
1548|    if (srcSize != ZSTD_CONTENTSIZE_UNKNOWN) {
1549|        U32 const dictAndWindowLog = ZSTD_dictAndWindowLog(cPar.windowLog, (U64)srcSize, (U64)dictSize);
