56|                                    int32_t min, int32_t max)
57|{
58|    FUZZ_ASSERT(min <= max);
59|
60|    if (min < 0)
61|      return (int)FUZZ_dataProducer_uint32Range(producer, 0, max - min) + min;
62|
63|    return FUZZ_dataProducer_uint32Range(producer, min, max);
